const ASSETS = {"index.html":{"body":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>Caption Studio</title>\n<link rel=\"stylesheet\" href=\"/style.css\" />\n</head>\n<body>\n<header class=\"topbar\">\n  <div class=\"brand\"><span class=\"dot\"></span> Caption&nbsp;Studio <em>local</em></div>\n  <div class=\"top-actions\">\n    <span id=\"caps\" class=\"caps\"></span>\n    <button id=\"btn-save\" class=\"ghost\" title=\"Save project JSON\">Save</button>\n    <button id=\"btn-load\" class=\"ghost\" title=\"Open project JSON\">Open</button>\n    <button id=\"btn-export\" class=\"primary\" disabled>Export video</button>\n  </div>\n</header>\n\n<main id=\"app\">\n  <!-- ---------------- left: style controls ---------------- -->\n  <aside class=\"panel left\">\n    <section>\n      <h3>Preset</h3>\n      <div id=\"presets\" class=\"preset-grid\"></div>\n    </section>\n\n    <section>\n      <h3>Animation</h3>\n      <div id=\"transitions\" class=\"chip-grid\"></div>\n      <label class=\"row\"><span>Speed</span>\n        <input type=\"range\" id=\"transitionMs\" min=\"90\" max=\"420\" step=\"10\" />\n        <output id=\"transitionMsOut\"></output>\n      </label>\n    </section>\n\n    <section>\n      <h3>Font</h3>\n      <div class=\"row\">\n        <select id=\"fontName\" class=\"grow\"></select>\n      </div>\n      <div class=\"row small\">\n        <label class=\"file ghost\">Add font file<input type=\"file\" id=\"fontFile\" accept=\".ttf,.otf,.ttc,.woff,.woff2\" hidden /></label>\n        <span class=\"hint\">for any language / brand font</span>\n      </div>\n      <label class=\"row\"><span>Size</span>\n        <input type=\"range\" id=\"fontSizePct\" min=\"2\" max=\"14\" step=\"0.2\" /><output id=\"fontSizePctOut\"></output>\n      </label>\n      <label class=\"row\"><span>Tracking</span>\n        <input type=\"range\" id=\"spacing\" min=\"-2\" max=\"12\" step=\"0.5\" /><output id=\"spacingOut\"></output>\n      </label>\n      <div class=\"row toggles\">\n        <button class=\"tgl\" data-toggle=\"bold\"><b>B</b></button>\n        <button class=\"tgl\" data-toggle=\"italic\"><i>I</i></button>\n        <button class=\"tgl\" data-toggle=\"underline\"><u>U</u></button>\n        <button class=\"tgl\" data-toggle=\"uppercase\">AA</button>\n      </div>\n    </section>\n\n    <section>\n      <h3>Colour</h3>\n      <label class=\"row\"><span>Text</span><input type=\"color\" id=\"textColor\" /></label>\n      <label class=\"row\"><span>Outline</span><input type=\"color\" id=\"outlineColor\" /></label>\n      <label class=\"row\"><span>Highlight</span><input type=\"color\" id=\"highlightColor\" /></label>\n      <label class=\"row\"><span>Box</span><input type=\"color\" id=\"boxColor\" /></label>\n      <label class=\"row\"><span>Backing</span>\n        <select id=\"boxStyle\">\n          <option value=\"outline\">Outline + shadow</option>\n          <option value=\"box\">Solid box</option>\n          <option value=\"none\">Plain text</option>\n        </select>\n      </label>\n      <label class=\"row\"><span>Outline w.</span>\n        <input type=\"range\" id=\"outlineWidth\" min=\"0\" max=\"12\" step=\"0.5\" /><output id=\"outlineWidthOut\"></output>\n      </label>\n      <label class=\"row\"><span>Shadow</span>\n        <input type=\"range\" id=\"shadowWidth\" min=\"0\" max=\"12\" step=\"0.5\" /><output id=\"shadowWidthOut\"></output>\n      </label>\n      <label class=\"row\"><span>Box alpha</span>\n        <input type=\"range\" id=\"boxOpacity\" min=\"0\" max=\"1\" step=\"0.05\" /><output id=\"boxOpacityOut\"></output>\n      </label>\n    </section>\n\n    <section>\n      <h3>Layout</h3>\n      <div class=\"align-grid\" id=\"alignGrid\"></div>\n      <label class=\"row\"><span>Side pad</span>\n        <input type=\"range\" id=\"marginXPct\" min=\"0\" max=\"25\" step=\"1\" /><output id=\"marginXPctOut\"></output>\n      </label>\n      <label class=\"row\"><span>Edge pad</span>\n        <input type=\"range\" id=\"marginYPct\" min=\"0\" max=\"45\" step=\"1\" /><output id=\"marginYPctOut\"></output>\n      </label>\n      <label class=\"row\"><span>Line length</span>\n        <input type=\"range\" id=\"maxChars\" min=\"10\" max=\"80\" step=\"1\" /><output id=\"maxCharsOut\"></output>\n      </label>\n    </section>\n  </aside>\n\n  <!-- ---------------- centre: video + preview ---------------- -->\n  <section class=\"stage\">\n    <div id=\"dropzone\" class=\"dropzone\">\n      <div class=\"dz-inner\">\n        <strong>Drop a video here</strong>\n        <span>mp4 · mov · webm · mkv · avi — never leaves your machine</span>\n        <label class=\"file primary\">Choose video<input type=\"file\" id=\"videoFile\" accept=\"video/*\" hidden /></label>\n      </div>\n    </div>\n\n    <div id=\"player\" class=\"player hidden\">\n      <div class=\"video-wrap\" id=\"videoWrap\">\n        <video id=\"video\" playsinline></video>\n        <div id=\"capLayer\" class=\"cap-layer\"><div id=\"capBox\" class=\"cap-box\"></div></div>\n      </div>\n      <div class=\"transport\">\n        <button id=\"btn-play\" class=\"ghost\">▶</button>\n        <input type=\"range\" id=\"seek\" min=\"0\" max=\"100\" step=\"0.01\" value=\"0\" class=\"grow\" />\n        <span id=\"time\" class=\"mono\">0:00 / 0:00</span>\n      </div>\n      <div id=\"timeline\" class=\"timeline\"></div>\n    </div>\n  </section>\n\n  <!-- ---------------- right: captions ---------------- -->\n  <aside class=\"panel right\">\n    <section>\n      <h3>Captions</h3>\n      <div class=\"row wrap gap\">\n        <button id=\"btn-auto\" class=\"primary\" disabled>Auto-caption</button>\n        <label class=\"file ghost\">Import SRT/VTT<input type=\"file\" id=\"subFile\" accept=\".srt,.vtt,.txt\" hidden /></label>\n        <button id=\"btn-add\" class=\"ghost\">+ Cue</button>\n      </div>\n      <label class=\"row\"><span>Language</span><select id=\"locale\" class=\"grow\"></select></label>\n      <label class=\"row\"><span>Model</span>\n        <select id=\"whisperModel\" class=\"grow\">\n          <option value=\"tiny\">tiny — fastest, roughest</option>\n          <option value=\"base\">base — fast</option>\n          <option value=\"small\" selected>small — balanced</option>\n          <option value=\"medium\">medium — slow, better</option>\n          <option value=\"turbo\">turbo — fast, near-large quality</option>\n        </select>\n      </label>\n      <label class=\"row\"><span>Max words/cue</span>\n        <input type=\"range\" id=\"wordsPerCue\" min=\"1\" max=\"14\" step=\"1\" /><output id=\"wordsPerCueOut\"></output>\n      </label>\n      <div class=\"row small\">\n        <button id=\"btn-resplit\" class=\"ghost\">Re-split cues</button>\n        <button id=\"btn-srt\" class=\"ghost\">.srt</button>\n        <button id=\"btn-ass\" class=\"ghost\">.ass</button>\n        <button id=\"btn-clear\" class=\"ghost danger\">Clear</button>\n      </div>\n      <p class=\"hint\" id=\"capHint\">No captions yet. Auto-caption, import a file, or add cues and type.</p>\n    </section>\n    <section class=\"grow-section\">\n      <div id=\"cues\" class=\"cues\"></div>\n    </section>\n  </aside>\n</main>\n\n<div id=\"modal\" class=\"modal hidden\">\n  <div class=\"modal-card\">\n    <h3 id=\"modalTitle\">Working…</h3>\n    <div class=\"bar\"><div id=\"modalBar\"></div></div>\n    <p id=\"modalMsg\" class=\"hint\"></p>\n    <pre id=\"modalLog\" class=\"log hidden\"></pre>\n    <div class=\"row end\"><a id=\"modalDl\" class=\"primary hidden\" download>Download</a><button id=\"modalClose\" class=\"ghost\">Close</button></div>\n  </div>\n</div>\n\n<input type=\"file\" id=\"projFile\" accept=\".json\" hidden />\n<script type=\"module\" src=\"/app.js\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"style.css":{"body":":root{\n  --bg:#0c0d11; --bg2:#13151c; --panel:#15171f; --line:#262a36; --line2:#323a4d;\n  --fg:#e9ecf4; --dim:#9aa2b6; --accent:#6c7bff; --accent2:#19d39a; --danger:#ff5f6b;\n  --radius:12px;\n}\n*{box-sizing:border-box}\nhtml,body{height:100%}\nbody{\n  margin:0; background:var(--bg); color:var(--fg);\n  font:14px/1.45 ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",Roboto,\"Noto Sans\",sans-serif;\n  overflow:hidden;\n}\nbutton,select,input,a.primary{font:inherit;color:inherit}\nh3{margin:0 0 10px;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--dim)}\n.hint{color:var(--dim);font-size:12px;margin:8px 0 0}\n.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;color:var(--dim)}\n.hidden{display:none !important}\n.grow{flex:1;min-width:0}\n\n/* ---------- chrome ---------- */\n.topbar{\n  height:52px;display:flex;align-items:center;justify-content:space-between;\n  padding:0 16px;background:var(--bg2);border-bottom:1px solid var(--line);\n}\n.brand{font-weight:650;letter-spacing:.01em;display:flex;align-items:center;gap:9px}\n.brand em{font-style:normal;font-size:10px;letter-spacing:.12em;text-transform:uppercase;\n  color:var(--accent2);border:1px solid #1d4d3d;background:#0f2a22;padding:2px 6px;border-radius:999px}\n.brand .dot{width:10px;height:10px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--accent2))}\n.top-actions{display:flex;align-items:center;gap:8px}\n.caps{font-size:11px;color:var(--dim)}\n\n#app{display:grid;grid-template-columns:280px 1fr 340px;height:calc(100% - 52px)}\n.panel{background:var(--panel);overflow-y:auto;display:flex;flex-direction:column}\n.panel.left{border-right:1px solid var(--line)}\n.panel.right{border-left:1px solid var(--line)}\n.panel section{padding:14px;border-bottom:1px solid var(--line)}\n.grow-section{flex:1;min-height:0;overflow-y:auto;border-bottom:none}\n\n/* ---------- controls ---------- */\nbutton,.file{\n  background:#1d2130;border:1px solid var(--line);color:var(--fg);\n  padding:7px 11px;border-radius:9px;cursor:pointer;transition:.12s;\n}\nbutton:hover,.file:hover{border-color:#3a4258}\nbutton:hover,.file:hover{background:#242938}\nbutton:disabled{opacity:.45;cursor:not-allowed}\n.primary{background:linear-gradient(135deg,var(--accent),#8a6cff);border-color:transparent;color:#fff;font-weight:600;text-decoration:none;display:inline-block}\n.ghost{background:#1a1e2a}\n.danger{color:var(--danger)}\n.file{display:inline-block}\n.row{display:flex;align-items:center;gap:8px;margin:7px 0}\n.row.wrap{flex-wrap:wrap}\n.row.small button,.row.small .file{padding:5px 9px;font-size:12px}\n.row.end{justify-content:flex-end;gap:8px}\n.row>span:first-child{width:72px;flex:none;color:var(--dim);font-size:12px}\n.row output{width:44px;text-align:right;font-family:ui-monospace,monospace;font-size:11px;color:var(--dim)}\ninput[type=range]{flex:1;min-width:0;accent-color:var(--accent);height:18px}\ninput[type=color]{width:42px;height:26px;padding:0;border:1px solid var(--line);border-radius:7px;background:none;cursor:pointer}\nselect{background:#1a1e2a;border:1px solid var(--line);border-radius:9px;padding:6px 8px;max-width:100%}\n.toggles{gap:6px}\n.tgl{width:36px;text-align:center;padding:6px 0}\n.tgl.on{background:var(--accent);border-color:transparent;color:#fff}\n\n.preset-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}\n.preset{padding:9px 6px;border-radius:9px;font-size:11px;text-align:center;line-height:1.2;\n  background:#191d29;border:1px solid var(--line);cursor:pointer;overflow:hidden}\n.preset.on{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent) inset}\n.preset b{display:block;font-size:12px}\n.chip-grid{display:flex;flex-wrap:wrap;gap:6px}\n.chip{padding:5px 9px;border-radius:999px;font-size:12px;background:#191d29;border:1px solid var(--line);cursor:pointer}\n.chip.on{background:var(--accent);border-color:transparent;color:#fff}\n.align-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-bottom:6px}\n.align-grid button{height:30px;padding:0;font-size:11px;color:var(--dim)}\n.align-grid button.on{background:var(--accent);color:#fff;border-color:transparent}\n\n/* ---------- stage ---------- */\n.stage{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:18px;gap:12px;min-width:0;overflow:hidden}\n.dropzone{width:100%;height:100%;border:2px dashed #2d3344;border-radius:18px;display:grid;place-items:center;\n  background:radial-gradient(900px 400px at 50% 0%,#161a26,transparent)}\n.dropzone.hot{border-color:var(--accent);background:#161b2e}\n.dz-inner{display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center}\n.dz-inner strong{font-size:19px}\n.dz-inner span{color:var(--dim);font-size:12px}\n\n.player{display:flex;flex-direction:column;gap:10px;width:100%;height:100%;min-height:0;align-items:center}\n.video-wrap{position:relative;flex:1;min-height:0;display:flex;align-items:center;justify-content:center;width:100%}\n#video{max-width:100%;max-height:100%;background:#000;border-radius:12px;display:block}\n.cap-layer{position:absolute;pointer-events:none;overflow:hidden;border-radius:12px}\n.cap-box{position:absolute;display:flex;flex-direction:column}\n.cap-line{display:block;width:fit-content}\n.cap-line span.w{white-space:pre}\n.transport{display:flex;align-items:center;gap:10px;width:100%;max-width:980px}\n.timeline{position:relative;height:40px;width:100%;max-width:980px;background:#12151e;border:1px solid var(--line);\n  border-radius:9px;overflow:hidden;flex:none}\n.tl-cue{position:absolute;top:5px;bottom:5px;background:#2b325a}\n.tl-cue{background:#2b325a;border:1px solid #47539b;border-radius:5px;overflow:hidden;font-size:10px;\n  color:#cdd4ff;padding:2px 4px;white-space:nowrap;cursor:pointer}\n.tl-cue.on{background:var(--accent);border-color:#fff3}\n.tl-head{position:absolute;top:0;bottom:0;width:2px;background:var(--accent2);pointer-events:none}\n\n/* ---------- cue list ---------- */\n.cues{display:flex;flex-direction:column}\n.cue{padding:9px 14px;border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:6px}\n.cue.on{background:#1a2033}\n.cue-head{display:flex;align-items:center;gap:6px}\n.cue-head input[type=number]{width:62px;background:#12151e;border:1px solid var(--line);border-radius:7px;\n  padding:4px 6px;font-family:ui-monospace,monospace;font-size:11px}\n.cue-head .spacer{flex:1}\n.cue-head button{padding:3px 7px;font-size:11px}\n.cue textarea{width:100%;background:#12151e;border:1px solid var(--line);border-radius:8px;color:var(--fg);\n  padding:7px 8px;resize:vertical;min-height:46px;font:inherit}\n\n/* ---------- modal ---------- */\n.modal{position:fixed;inset:0;background:#05060acc;display:grid;place-items:center;z-index:50}\n.modal-card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px;width:min(560px,92vw)}\n.bar{height:8px;background:#12151e;border-radius:999px;overflow:hidden;margin:10px 0}\n.bar>div{height:100%;width:0;background:linear-gradient(90deg,var(--accent),var(--accent2));transition:width .25s}\n.log{max-height:180px;overflow:auto;background:#0b0d13;border:1px solid var(--line);border-radius:8px;\n  padding:8px;font-size:11px;color:#c6b2a0;white-space:pre-wrap}\n\n/* ---------- caption animations (preview only) ---------- */\n@keyframes cs-fade{from{opacity:0}to{opacity:1}}\n@keyframes cs-up{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}\n@keyframes cs-down{from{opacity:0;transform:translateY(-26px)}to{opacity:1;transform:none}}\n@keyframes cs-left{from{opacity:0;transform:translateX(44px)}to{opacity:1;transform:none}}\n@keyframes cs-right{from{opacity:0;transform:translateX(-44px)}to{opacity:1;transform:none}}\n@keyframes cs-pop{from{opacity:0;transform:scale(.55)}to{opacity:1;transform:scale(1)}}\n@keyframes cs-bounce{0%{opacity:0;transform:scale(1.18)}55%{opacity:1;transform:scale(.92)}100%{transform:scale(1)}}\n@keyframes cs-blur{from{opacity:0;filter:blur(8px)}to{opacity:1;filter:blur(0)}}\n@keyframes cs-zoom{from{transform:scale(1.35)}to{transform:scale(1)}}\n.anim-fade{animation:cs-fade var(--tdur) ease both}\n.anim-slide-up{animation:cs-up var(--tdur) cubic-bezier(.2,.8,.2,1) both}\n.anim-slide-down{animation:cs-down var(--tdur) cubic-bezier(.2,.8,.2,1) both}\n.anim-slide-left{animation:cs-left var(--tdur) cubic-bezier(.2,.8,.2,1) both}\n.anim-slide-right{animation:cs-right var(--tdur) cubic-bezier(.2,.8,.2,1) both}\n.anim-pop{animation:cs-pop var(--tdur) cubic-bezier(.2,1.5,.3,1) both}\n.anim-bounce{animation:cs-bounce var(--tdur) ease-out both}\n.anim-blur-in{animation:cs-blur var(--tdur) ease both}\n.anim-zoom-out{animation:cs-zoom var(--cdur) ease-out both}\n\n@media (max-width:1100px){\n  #app{grid-template-columns:240px 1fr 290px}\n}\n","type":"text/css; charset=utf-8"},"app.js":{"body":"import { wrapText, TRANSITIONS } from '/lib/ass.mjs';\n\nconst $ = (id) => document.getElementById(id);\nconst clamp = (v, a, b) => Math.min(b, Math.max(a, v));\n\n/* ------------------------------- state ---------------------------------- */\n\nconst DEFAULT_STYLE = {\n  fontName: 'DejaVu Sans', fontSizePct: 5.6, bold: true, italic: false, underline: false,\n  uppercase: false, spacing: 0, textColor: '#ffffff', textOpacity: 1,\n  outlineColor: '#000000', outlineWidth: 3, shadowWidth: 1.5,\n  highlightColor: '#ffd400', boxColor: '#000000', boxOpacity: 0.55, boxStyle: 'outline',\n  alignment: 2, marginXPct: 6, marginYPct: 9, maxChars: 32, transitionMs: 260, locale: 'auto',\n};\n\nconst PRESETS = [\n  { name: 'Clean', sub: 'white + outline', style: {} },\n  { name: 'Pop', sub: 'big & punchy', style: { fontSizePct: 7.4, outlineWidth: 5, maxChars: 18, boxStyle: 'outline', shadowWidth: 0 }, transition: 'pop' },\n  { name: 'Sing-along', sub: 'word highlight', style: { fontSizePct: 6.8, highlightColor: '#ffe14d', outlineWidth: 4.5, maxChars: 24 }, transition: 'karaoke' },\n  { name: 'Bar', sub: 'solid backing', style: { boxStyle: 'box', boxColor: '#000000', boxOpacity: 0.78, outlineWidth: 0, fontSizePct: 5, maxChars: 44 }, transition: 'fade' },\n  { name: 'Neon', sub: 'glow accent', style: { textColor: '#8ef7ff', outlineColor: '#07213a', outlineWidth: 4, shadowWidth: 4, fontSizePct: 6.4, maxChars: 22 }, transition: 'blur-in' },\n  { name: 'Headline', sub: 'top, all caps', style: { alignment: 8, uppercase: true, fontSizePct: 6, spacing: 2, marginYPct: 8, maxChars: 26 }, transition: 'slide-down' },\n  { name: 'Typed', sub: 'typewriter', style: { fontSizePct: 5.2, maxChars: 38, boxStyle: 'box', boxOpacity: 0.5 }, transition: 'typewriter' },\n  { name: 'Centre', sub: 'middle of frame', style: { alignment: 5, fontSizePct: 8, maxChars: 16, outlineWidth: 5 }, transition: 'bounce' },\n];\n\nconst LOCALES = [\n  ['auto', 'Auto-detect'],\n  ['en', 'English'], ['es', 'Español'], ['pt', 'Português'], ['fr', 'Français'], ['de', 'Deutsch'],\n  ['it', 'Italiano'], ['nl', 'Nederlands'], ['pl', 'Polski'], ['tr', 'Türkçe'], ['ro', 'Română'],\n  ['sv', 'Svenska'], ['da', 'Dansk'], ['fi', 'Suomi'], ['cs', 'Čeština'], ['el', 'Ελληνικά'],\n  ['ru', 'Русский'], ['uk', 'Українська'], ['sr', 'Српски'], ['ar', 'العربية'], ['he', 'עברית'],\n  ['fa', 'فارسی'], ['ur', 'اردو'], ['hi', 'हिन्दी'], ['bn', 'বাংলা'], ['ta', 'தமிழ்'],\n  ['te', 'తెలుగు'], ['mr', 'मराठी'], ['gu', 'ગુજરાતી'], ['pa', 'ਪੰਜਾਬੀ'], ['si', 'සිංහල'],\n  ['th', 'ไทย'], ['lo', 'ລາວ'], ['km', 'ខ្មែរ'], ['my', 'မြန်မာ'], ['vi', 'Tiếng Việt'],\n  ['id', 'Bahasa Indonesia'], ['ms', 'Bahasa Melayu'], ['tl', 'Filipino'], ['sw', 'Kiswahili'],\n  ['am', 'አማርኛ'], ['ha', 'Hausa'], ['yo', 'Yorùbá'], ['zh', '中文 (简体)'], ['zh-Hant', '中文 (繁體)'],\n  ['ja', '日本語'], ['ko', '한국어'], ['ka', 'ქართული'], ['hy', 'Հայերեն'], ['az', 'Azərbaycan'],\n  ['kk', 'Қазақша'], ['uz', 'Oʻzbekcha'], ['ne', 'नेपाली'], ['mn', 'Монгол'],\n];\nconst RTL = new Set(['ar', 'he', 'fa', 'ur', 'ps', 'sd', 'ckb', 'yi']);\n\nconst state = {\n  media: null,\n  cues: [],\n  style: { ...DEFAULT_STYLE },\n  transition: 'slide-up',\n  activePreset: 0,\n  selected: -1,\n  caps: { whisper: false, fonts: [], transitions: TRANSITIONS },\n  wordsPerCue: 5,\n  transcribing: false,\n  runId: 0,\n};\n\n/* ------------------------------ bootstrap -------------------------------- */\n\nconst video = $('video');\n\nasync function boot() {\n  try {\n    const caps = await (await fetch('/api/capabilities')).json();\n    state.caps = { ...state.caps, ...caps };\n    $('caps').textContent =\n      `${caps.ffmpeg ? 'ffmpeg ✓' : 'ffmpeg ✗'} · ${caps.whisper ? 'auto-captions ✓' : 'auto-captions ✗'}`;\n    $('btn-auto').disabled = !caps.whisper;\n    $('btn-auto').title = caps.whisper ? 'Transcribe with local Whisper'\n      : 'Install the Whisper CLI (pip install -U openai-whisper) to auto-caption';\n    fillFonts(caps.fonts || [], caps.customFonts || []);\n  } catch {\n    $('caps').textContent = 'server unreachable';\n  }\n  buildPresets();\n  buildTransitions();\n  buildAlignGrid();\n  fillLocales();\n  bindStyleInputs();\n  bindActions();\n  syncInputs();\n  renderCues();\n  tick();\n}\n\nfunction fillFonts(families, custom) {\n  const sel = $('fontName');\n  sel.innerHTML = '';\n  const seen = new Set();\n  const add = (fam, group) => {\n    if (seen.has(fam)) return;\n    seen.add(fam);\n    const o = document.createElement('option');\n    o.value = fam; o.textContent = fam;\n    (group || sel).appendChild(o);\n  };\n  if (custom.length) {\n    const g = document.createElement('optgroup'); g.label = 'Added by you';\n    custom.forEach((c) => { registerFont(c.family, c.url || `/api/fonts/${c.file}`); add(c.family, g); });\n    sel.appendChild(g);\n  }\n  const g2 = document.createElement('optgroup'); g2.label = 'Installed on this machine';\n  families.forEach((f) => add(f, g2));\n  sel.appendChild(g2);\n  if (!seen.has(state.style.fontName)) {\n    const pick = families.find((f) => /dejavu sans$|^arial$|^helvetica$|^inter$|liberation sans/i.test(f));\n    if (pick) state.style.fontName = pick;\n  }\n  sel.value = state.style.fontName;\n}\n\nfunction registerFont(family, url) {\n  try {\n    const ff = new FontFace(family, `url(\"${url}\")`);\n    ff.load().then((f) => document.fonts.add(f)).catch(() => {});\n  } catch { /* ignore */ }\n}\n\nfunction buildPresets() {\n  const host = $('presets');\n  host.innerHTML = '';\n  PRESETS.forEach((p, i) => {\n    const b = document.createElement('button');\n    b.className = 'preset' + (i === state.activePreset ? ' on' : '');\n    b.innerHTML = `<b>${p.name}</b>${p.sub}`;\n    b.onclick = () => {\n      state.activePreset = i;\n      state.style = { ...DEFAULT_STYLE, ...p.style, fontName: state.style.fontName, locale: state.style.locale };\n      if (p.transition) state.transition = p.transition;\n      buildPresets(); buildTransitions(); syncInputs(); drawCaption(true);\n    };\n    host.appendChild(b);\n  });\n}\n\nconst TRANSITION_LABELS = {\n  none: 'None', fade: 'Fade', 'slide-up': 'Slide up', 'slide-down': 'Slide down',\n  'slide-left': 'Slide ←', 'slide-right': 'Slide →', pop: 'Pop', bounce: 'Bounce',\n  'blur-in': 'Blur in', 'zoom-out': 'Zoom out', typewriter: 'Typewriter',\n  'word-pop': 'Word by word', karaoke: 'Karaoke',\n};\n\nfunction buildTransitions() {\n  const host = $('transitions');\n  host.innerHTML = '';\n  (state.caps.transitions || TRANSITIONS).forEach((t) => {\n    const b = document.createElement('button');\n    b.className = 'chip' + (t === state.transition ? ' on' : '');\n    b.textContent = TRANSITION_LABELS[t] || t;\n    b.onclick = () => { state.transition = t; buildTransitions(); drawCaption(true); };\n    host.appendChild(b);\n  });\n}\n\nfunction buildAlignGrid() {\n  const host = $('alignGrid');\n  const labels = { 7: '↖', 8: '↑', 9: '↗', 4: '←', 5: '•', 6: '→', 1: '↙', 2: '↓', 3: '↘' };\n  host.innerHTML = '';\n  [7, 8, 9, 4, 5, 6, 1, 2, 3].forEach((a) => {\n    const b = document.createElement('button');\n    b.textContent = labels[a];\n    b.className = state.style.alignment === a ? 'on' : '';\n    b.onclick = () => { state.style.alignment = a; buildAlignGrid(); drawCaption(true); };\n    host.appendChild(b);\n  });\n}\n\nfunction fillLocales() {\n  const sel = $('locale');\n  sel.innerHTML = '';\n  LOCALES.forEach(([code, label]) => {\n    const o = document.createElement('option');\n    o.value = code; o.textContent = `${label} (${code})`;\n    sel.appendChild(o);\n  });\n  sel.value = state.style.locale;\n  sel.onchange = () => { state.style.locale = sel.value; drawCaption(true); renderCues(); };\n}\n\n/* --------------------------- style bindings ------------------------------ */\n\nconst RANGES = ['fontSizePct', 'spacing', 'outlineWidth', 'shadowWidth', 'boxOpacity',\n                'marginXPct', 'marginYPct', 'maxChars', 'transitionMs'];\nconst COLORS = ['textColor', 'outlineColor', 'highlightColor', 'boxColor'];\n\nfunction bindStyleInputs() {\n  RANGES.forEach((k) => {\n    const el = $(k);\n    el.oninput = () => {\n      state.style[k] = Number(el.value);\n      $(k + 'Out').value = el.value;\n      drawCaption(k === 'transitionMs');\n    };\n  });\n  COLORS.forEach((k) => { $(k).oninput = () => { state.style[k] = $(k).value; drawCaption(); }; });\n  $('fontName').onchange = () => { state.style.fontName = $('fontName').value; drawCaption(); };\n  $('boxStyle').onchange = () => { state.style.boxStyle = $('boxStyle').value; drawCaption(); };\n  document.querySelectorAll('[data-toggle]').forEach((b) => {\n    b.onclick = () => {\n      const k = b.dataset.toggle;\n      state.style[k] = !state.style[k];\n      b.classList.toggle('on', !!state.style[k]);\n      drawCaption();\n    };\n  });\n  $('wordsPerCue').oninput = () => {\n    state.wordsPerCue = Number($('wordsPerCue').value);\n    $('wordsPerCueOut').value = state.wordsPerCue;\n  };\n}\n\nfunction syncInputs() {\n  RANGES.forEach((k) => { $(k).value = state.style[k]; $(k + 'Out').value = state.style[k]; });\n  COLORS.forEach((k) => { $(k).value = state.style[k]; });\n  $('boxStyle').value = state.style.boxStyle;\n  $('fontName').value = state.style.fontName;\n  $('wordsPerCue').value = state.wordsPerCue;\n  $('wordsPerCueOut').value = state.wordsPerCue;\n  document.querySelectorAll('[data-toggle]').forEach((b) => {\n    b.classList.toggle('on', !!state.style[b.dataset.toggle]);\n  });\n  buildAlignGrid();\n}\n\n/* ------------------------------- preview -------------------------------- */\n\nfunction videoRect() {\n  const wrap = $('videoWrap').getBoundingClientRect();\n  const r = video.getBoundingClientRect();\n  return { left: r.left - wrap.left, top: r.top - wrap.top, width: r.width, height: r.height };\n}\n\nfunction syncLayer() {\n  const r = videoRect();\n  const layer = $('capLayer');\n  layer.style.left = r.left + 'px';\n  layer.style.top = r.top + 'px';\n  layer.style.width = r.width + 'px';\n  layer.style.height = r.height + 'px';\n}\n\nfunction activeCue(t) {\n  for (let i = 0; i < state.cues.length; i++) {\n    const c = state.cues[i];\n    if (t >= c.start && t < c.end) return { cue: c, index: i };\n  }\n  return null;\n}\n\nfunction segments(text, locale, granularity) {\n  if (locale === 'auto') locale = undefined;\n  if (window.Intl && Intl.Segmenter) {\n    try {\n      return [...new Intl.Segmenter(locale || undefined, { granularity }).segment(text)]\n        .map((s) => ({ text: s.segment, wordLike: !!s.isWordLike }));\n    } catch { /* fall through */ }\n  }\n  if (granularity === 'grapheme') return [...text].map((c) => ({ text: c, wordLike: /\\S/.test(c) }));\n  return text.split(/(\\s+)/).filter(Boolean).map((t) => ({ text: t, wordLike: /\\S/.test(t) }));\n}\n\nlet lastKey = '';\n\nfunction drawCaption(forceRestart = false) {\n  syncLayer();\n  const box = $('capBox');\n  const st = state.style;\n  const r = videoRect();\n  const H = r.height || 1;\n  const hit = activeCue(video.currentTime || 0);\n  const demo = !state.media || !hit;\n\n  const cue = hit?.cue || (state.cues[Math.max(0, state.selected)] ||\n    { start: 0, end: 3, text: 'Your captions preview here', locale: st.locale });\n  const locale = cue.locale || st.locale;\n  let raw = String(cue.text || '').trim();\n  if (!raw) { box.innerHTML = ''; return; }\n  if (st.uppercase) { try { raw = raw.toLocaleUpperCase(locale === 'auto' ? undefined : locale); } catch { raw = raw.toUpperCase(); } }\n  const lines = wrapText(raw, st.maxChars, locale);\n\n  // geometry\n  const mx = (st.marginXPct / 100) * r.width;\n  const my = (st.marginYPct / 100) * H;\n  const a = st.alignment;\n  const col = (a - 1) % 3, row = Math.floor((a - 1) / 3);\n  box.style.left = col === 0 ? mx + 'px' : col === 1 ? mx + 'px' : 'auto';\n  box.style.right = col === 2 ? mx + 'px' : mx + 'px';\n  box.style.width = `calc(100% - ${mx * 2}px)`;\n  box.style.top = row === 2 ? my + 'px' : row === 1 ? '50%' : 'auto';\n  box.style.bottom = row === 0 ? my + 'px' : 'auto';\n  box.style.transform = row === 1 ? 'translateY(-50%)' : 'none';\n  box.style.alignItems = col === 0 ? 'flex-start' : col === 2 ? 'flex-end' : 'center';\n  box.style.textAlign = col === 0 ? 'left' : col === 2 ? 'right' : 'center';\n\n  // typography\n  const fs = (st.fontSizePct / 100) * H;\n  const ow = (st.outlineWidth / 100) * H * 0.55;\n  const sh = (st.shadowWidth / 100) * H * 0.55;\n  box.style.font = `${st.italic ? 'italic ' : ''}${st.bold ? '800' : '500'} ${fs}px/1.22 \"${st.fontName}\", \"Noto Sans\", sans-serif`;\n  box.style.letterSpacing = (st.spacing / 100) * H * 0.3 + 'px';\n  box.style.color = st.textColor;\n  box.style.textDecoration = st.underline ? 'underline' : 'none';\n  box.style.gap = fs * 0.12 + 'px';\n  box.dir = RTL.has(String(locale).split('-')[0]) ? 'rtl' : 'auto';\n\n  const stroke = st.boxStyle === 'none' ? 'none' : `${ow}px ${st.outlineColor}`;\n  const shadow = st.boxStyle === 'none' || !sh ? 'none'\n    : `${sh * 0.6}px ${sh}px ${sh * 0.9}px ${hexAlpha(st.outlineColor, 0.85)}`;\n\n  const dur = st.transitionMs;\n  const kind = cue.transition || state.transition;\n  const key = `${hit ? hit.index : 'demo'}|${kind}|${dur}|${raw}|${st.maxChars}`;\n  const restart = forceRestart || key !== lastKey;\n  lastKey = key;\n\n  const progress = clamp(((video.currentTime || 0) - cue.start) / Math.max(0.05, cue.end - cue.start), 0, 1);\n\n  box.innerHTML = '';\n  const animClass = ['typewriter', 'word-pop', 'karaoke', 'none'].includes(kind) ? '' : 'anim-' + kind;\n\n  const makeLine = () => {\n    const d = document.createElement('div');\n    d.className = 'cap-line ' + animClass;\n    d.style.webkitTextStroke = stroke === 'none' ? '' : stroke;\n    d.style.paintOrder = 'stroke fill';\n    d.style.textShadow = shadow;\n    if (st.boxStyle === 'box') {\n      d.style.background = hexAlpha(st.boxColor, st.boxOpacity);\n      d.style.padding = `${fs * 0.1}px ${fs * 0.28}px`;\n      d.style.borderRadius = fs * 0.14 + 'px';\n    }\n    d.style.setProperty('--tdur', dur + 'ms');\n    d.style.setProperty('--cdur', Math.max(0.1, cue.end - cue.start) + 's');\n    return d;\n  };\n\n  if (kind === 'karaoke' || kind === 'word-pop' || kind === 'typewriter') {\n    const gran = kind === 'typewriter' ? 'grapheme' : 'word';\n    const all = lines.map((l) => segments(l, locale, gran));\n    const total = all.flat().filter((s) => s.wordLike || gran === 'grapheme').length || 1;\n    let seen = 0;\n    for (const lineSegs of all) {\n      const d = makeLine();\n      for (const s of lineSegs) {\n        const el = document.createElement('span');\n        el.className = 'w';\n        el.textContent = s.text;\n        const isUnit = s.wordLike || gran === 'grapheme';\n        if (isUnit) {\n          seen += 1;\n          const reached = progress * total >= seen - 1;\n          if (kind === 'karaoke') el.style.color = reached ? st.highlightColor : st.textColor;\n          else el.style.visibility = reached ? 'visible' : 'hidden';\n        }\n        d.appendChild(el);\n      }\n      box.appendChild(d);\n    }\n  } else {\n    for (const l of lines) {\n      const d = makeLine();\n      d.textContent = l || ' ';\n      box.appendChild(d);\n    }\n  }\n  if (restart) {\n    box.querySelectorAll('.cap-line').forEach((el) => { el.style.animation = 'none'; void el.offsetWidth; el.style.animation = ''; });\n  }\n  box.style.opacity = demo ? 0.55 : 1;\n}\n\nfunction hexAlpha(hex, a) {\n  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || '#000000'));\n  const h = m ? m[1] : '000000';\n  return `rgba(${parseInt(h.slice(0, 2), 16)},${parseInt(h.slice(2, 4), 16)},${parseInt(h.slice(4, 6), 16)},${a})`;\n}\n\nfunction tick() {\n  drawCaption();\n  drawPlayhead();\n  updateTime();\n  requestAnimationFrame(tick);\n}\n\n/* ------------------------------ timeline -------------------------------- */\n\nfunction renderTimeline() {\n  const host = $('timeline');\n  const dur = state.media?.duration || video.duration || 0;\n  host.querySelectorAll('.tl-cue').forEach((n) => n.remove());\n  if (!dur) return;\n  state.cues.forEach((c, i) => {\n    const el = document.createElement('div');\n    el.className = 'tl-cue' + (i === state.selected ? ' on' : '');\n    el.style.left = (c.start / dur) * 100 + '%';\n    el.style.width = Math.max(0.4, ((c.end - c.start) / dur) * 100) + '%';\n    el.textContent = c.text.slice(0, 40);\n    el.title = `${c.start.toFixed(2)}s → ${c.end.toFixed(2)}s`;\n    el.onclick = () => { select(i); video.currentTime = c.start + 0.01; };\n    host.appendChild(el);\n  });\n}\n\nfunction drawPlayhead() {\n  const dur = state.media?.duration || video.duration || 0;\n  let head = $('timeline').querySelector('.tl-head');\n  if (!head) { head = document.createElement('div'); head.className = 'tl-head'; $('timeline').appendChild(head); }\n  head.style.left = dur ? ((video.currentTime || 0) / dur) * 100 + '%' : '0%';\n}\n\nconst fmt = (s) => {\n  s = Math.max(0, s || 0);\n  const m = Math.floor(s / 60);\n  return `${m}:${String(Math.floor(s % 60)).padStart(2, '0')}`;\n};\n\nfunction updateTime() {\n  const dur = video.duration || state.media?.duration || 0;\n  $('time').textContent = `${fmt(video.currentTime)} / ${fmt(dur)}`;\n  if (dur) $('seek').value = String(((video.currentTime || 0) / dur) * 100);\n}\n\n/* ------------------------------- cue list -------------------------------- */\n\nfunction select(i) {\n  state.selected = i;\n  // Update highlighting in place. Rebuilding the list here would destroy the\n  // textarea the user just clicked into, so typing would never land.\n  const nodes = $('cues').children;\n  for (let k = 0; k < nodes.length; k++) nodes[k].classList.toggle('on', k === i);\n  renderTimeline();\n}\n\nfunction renderCues() {\n  const host = $('cues');\n  host.innerHTML = '';\n  $('capHint').classList.toggle('hidden', state.cues.length > 0);\n  state.cues.forEach((c, i) => {\n    const el = document.createElement('div');\n    el.className = 'cue' + (i === state.selected ? ' on' : '');\n    const head = document.createElement('div');\n    head.className = 'cue-head';\n    head.innerHTML =\n      `<input type=\"number\" step=\"0.05\" min=\"0\" value=\"${c.start.toFixed(2)}\" data-k=\"start\" />` +\n      `<span class=\"mono\">→</span>` +\n      `<input type=\"number\" step=\"0.05\" min=\"0\" value=\"${c.end.toFixed(2)}\" data-k=\"end\" />` +\n      `<span class=\"spacer\"></span>` +\n      `<button data-a=\"here\" title=\"Set start to playhead\">⏱</button>` +\n      `<button data-a=\"play\" title=\"Play this cue\">▶</button>` +\n      `<button data-a=\"split\" title=\"Split in half\">⇄</button>` +\n      `<button data-a=\"del\" class=\"danger\" title=\"Delete\">✕</button>`;\n    const ta = document.createElement('textarea');\n    ta.value = c.text;\n    ta.dir = 'auto';\n    ta.spellcheck = false;\n    ta.oninput = () => { c.text = ta.value; renderTimeline(); drawCaption(true); };\n    ta.onfocus = () => select(i);\n    el.append(head, ta);\n\n    head.querySelectorAll('input').forEach((inp) => {\n      inp.onchange = () => {\n        const v = Math.max(0, Number(inp.value) || 0);\n        c[inp.dataset.k] = v;\n        if (c.end <= c.start) c.end = c.start + 0.4;\n        normalise();\n        renderCues(); renderTimeline();\n      };\n    });\n    head.querySelectorAll('button').forEach((b) => {\n      b.onclick = () => {\n        const a = b.dataset.a;\n        if (a === 'del') { state.cues.splice(i, 1); state.selected = -1; }\n        else if (a === 'here') { const d = c.end - c.start; c.start = video.currentTime; c.end = c.start + d; }\n        else if (a === 'play') { video.currentTime = c.start + 0.01; video.play(); }\n        else if (a === 'split') {\n          const mid = (c.start + c.end) / 2;\n          const words = c.text.split(/\\s+/);\n          const half = Math.ceil(words.length / 2);\n          const second = { start: mid, end: c.end, text: words.slice(half).join(' '), locale: c.locale };\n          c.end = mid; c.text = words.slice(0, half).join(' ');\n          state.cues.splice(i + 1, 0, second);\n        }\n        normalise(); renderCues(); renderTimeline(); drawCaption(true);\n      };\n    });\n    el.onclick = (e) => { if (e.target === el) select(i); };\n    host.appendChild(el);\n  });\n  renderTimeline();\n}\n\nfunction normalise() {\n  state.cues.sort((a, b) => a.start - b.start);\n  state.cues.forEach((c) => {\n    c.start = Math.max(0, Number(c.start) || 0);\n    c.end = Math.max(c.start + 0.2, Number(c.end) || c.start + 1);\n  });\n}\n\n/* --------------------------- import / split ------------------------------ */\n\nfunction parseTime(s) {\n  const m = /(\\d+):(\\d{1,2}):(\\d{1,2})[.,](\\d{1,3})/.exec(s) || /(\\d{1,2}):(\\d{1,2})[.,](\\d{1,3})/.exec(s);\n  if (!m) return 0;\n  if (m.length === 5) return +m[1] * 3600 + +m[2] * 60 + +m[3] + +('0.' + m[4]);\n  return +m[1] * 60 + +m[2] + +('0.' + m[3]);\n}\n\nfunction parseSubtitles(txt) {\n  const clean = txt.replace(/\\r/g, '').replace(/^WEBVTT.*\\n/, '');\n  const cues = [];\n  for (const block of clean.split(/\\n{2,}/)) {\n    const lines = block.split('\\n').filter((l) => l.trim());\n    if (!lines.length) continue;\n    const tIdx = lines.findIndex((l) => l.includes('-->'));\n    if (tIdx < 0) continue;\n    const [a, b] = lines[tIdx].split('-->');\n    const text = lines.slice(tIdx + 1).join('\\n').trim();\n    if (!text) continue;\n    cues.push({ start: parseTime(a), end: parseTime(b), text, locale: state.style.locale });\n  }\n  return cues;\n}\n\n/** Re-chunk cues into n-word pieces, timing split by unit count. */\nfunction resplit(cues, perCue, locale) {\n  const out = [];\n  for (const c of cues) {\n    const units = segments(c.text.replace(/\\n/g, ' '), locale, 'word').filter((s) => s.text.trim());\n    const words = units.filter((u) => u.wordLike).map((u) => u.text);\n    if (words.length <= perCue) { out.push({ ...c }); continue; }\n    const chunks = [];\n    for (let i = 0; i < words.length; i += perCue) chunks.push(words.slice(i, i + perCue));\n    const dur = c.end - c.start;\n    const totalW = words.length;\n    let t = c.start;\n    chunks.forEach((ch) => {\n      const d = dur * (ch.length / totalW);\n      const needsSpace = /\\s/.test(c.text);\n      out.push({ start: t, end: t + d, text: ch.join(needsSpace ? ' ' : ''), locale: c.locale });\n      t += d;\n    });\n  }\n  return out;\n}\n\n/* -------------------------------- actions -------------------------------- */\n\nfunction modal(title, msg, { progress = null, log = null, download = null } = {}) {\n  $('modal').classList.remove('hidden');\n  $('modalTitle').textContent = title;\n  $('modalMsg').textContent = msg || '';\n  $('modalBar').style.width = (progress ?? 0) + '%';\n  $('modalLog').classList.toggle('hidden', !log);\n  if (log) $('modalLog').textContent = log;\n  const dl = $('modalDl');\n  dl.classList.toggle('hidden', !download);\n  if (download) dl.href = download;\n}\n\nasync function uploadVideo(file) {\n  modal('Reading video…', file.name, { progress: 8 });\n  const res = await fetch(`/api/upload?name=${encodeURIComponent(file.name)}`, {\n    method: 'PUT', body: file, headers: { 'content-type': file.type || 'application/octet-stream' },\n  });\n  const data = await res.json();\n  if (!res.ok) { modal('Upload failed', data.error || 'unknown error'); return; }\n  state.media = data;\n  video.src = data.url;\n  $('dropzone').classList.add('hidden');\n  $('player').classList.remove('hidden');\n  $('btn-export').disabled = false;\n  $('modal').classList.add('hidden');\n  await video.play().catch(() => {});\n  video.pause();\n  renderTimeline();\n}\n\nasync function poll(jobId, onProgress) {\n  for (;;) {\n    await new Promise((r) => setTimeout(r, 700));\n    const j = await (await fetch('/api/job/' + jobId)).json();\n    onProgress?.(j);\n    if (j.status === 'done' || j.status === 'error') return j;\n  }\n}\n\nfunction payload(extra = {}) {\n  return {\n    mediaId: state.media?.id,\n    cues: state.cues,\n    style: state.style,\n    transition: state.transition,\n    width: state.media?.width,\n    height: state.media?.height,\n    ...extra,\n  };\n}\n\nfunction bindActions() {\n  // upload\n  const dz = $('dropzone');\n  const onFiles = (files) => { const f = [...files].find((f) => /^video\\//.test(f.type) || /\\.(mp4|mov|mkv|webm|avi|m4v)$/i.test(f.name)); if (f) uploadVideo(f); };\n  $('videoFile').onchange = (e) => onFiles(e.target.files);\n  ['dragenter', 'dragover'].forEach((ev) => document.addEventListener(ev, (e) => { e.preventDefault(); dz.classList.add('hot'); }));\n  ['dragleave', 'drop'].forEach((ev) => document.addEventListener(ev, (e) => { e.preventDefault(); if (ev === 'drop') onFiles(e.dataTransfer.files); dz.classList.remove('hot'); }));\n\n  // transport\n  $('btn-play').onclick = () => (video.paused ? video.play() : video.pause());\n  video.onplay = () => ($('btn-play').textContent = '❚❚');\n  video.onpause = () => ($('btn-play').textContent = '▶');\n  video.onloadedmetadata = () => { syncLayer(); renderTimeline(); };\n  $('seek').oninput = () => {\n    const dur = video.duration || 0;\n    if (dur) video.currentTime = (Number($('seek').value) / 100) * dur;\n    drawCaption(true);\n  };\n  $('timeline').onclick = (e) => {\n    if (e.target !== $('timeline')) return;\n    const r = $('timeline').getBoundingClientRect();\n    const dur = video.duration || 0;\n    if (dur) video.currentTime = ((e.clientX - r.left) / r.width) * dur;\n  };\n  window.addEventListener('resize', () => { syncLayer(); drawCaption(true); });\n  document.addEventListener('keydown', (e) => {\n    if (/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)) return;\n    if (e.code === 'Space') { e.preventDefault(); video.paused ? video.play() : video.pause(); }\n    if (e.code === 'ArrowLeft') video.currentTime = Math.max(0, video.currentTime - (e.shiftKey ? 1 : 0.2));\n    if (e.code === 'ArrowRight') video.currentTime += e.shiftKey ? 1 : 0.2;\n  });\n\n  // fonts\n  $('fontFile').onchange = async (e) => {\n    const f = e.target.files[0];\n    if (!f) return;\n    const res = await fetch(`/api/fonts?name=${encodeURIComponent(f.name)}`, { method: 'PUT', body: f });\n    const d = await res.json();\n    if (!res.ok) return modal('Font rejected', d.error || '');\n    const caps = await (await fetch('/api/capabilities')).json();\n    state.style.fontName = d.family;\n    fillFonts(caps.fonts || [], caps.customFonts || []);\n    registerFont(d.family, d.url);\n    $('fontName').value = d.family;\n    drawCaption(true);\n  };\n\n  // captions\n  $('btn-add').onclick = () => {\n    const t = video.currentTime || 0;\n    state.cues.push({ start: t, end: t + 2, text: 'New caption', locale: state.style.locale });\n    normalise();\n    state.selected = state.cues.findIndex((c) => c.start === t);\n    renderCues(); drawCaption(true);\n  };\n  $('btn-clear').onclick = () => { if (confirm('Remove all captions?')) { state.cues = []; state.selected = -1; renderCues(); } };\n  $('subFile').onchange = async (e) => {\n    const f = e.target.files[0];\n    if (!f) return;\n    const txt = await f.text();\n    let cues = parseSubtitles(txt);\n    if (!cues.length) {\n      // plain text: spread evenly across the video\n      const dur = video.duration || state.media?.duration || 30;\n      const parts = txt.split(/\\n+/).map((s) => s.trim()).filter(Boolean);\n      const each = dur / Math.max(1, parts.length);\n      cues = parts.map((text, i) => ({ start: i * each, end: (i + 1) * each, text, locale: state.style.locale }));\n    }\n    state.cues = resplit(cues, state.wordsPerCue, state.style.locale);\n    normalise(); renderCues(); drawCaption(true);\n  };\n  $('btn-resplit').onclick = () => {\n    state.cues = resplit(state.cues, state.wordsPerCue, state.style.locale);\n    normalise(); renderCues(); drawCaption(true);\n  };\n  $('btn-auto').onclick = async () => {\n    if (!state.media) return modal('No video', 'Add a video first.');\n    if (state.transcribing) return;            // a second run would fight the first\n    state.transcribing = true;\n    $('btn-auto').disabled = true;\n    const myRun = ++state.runId;\n    const mine = () => myRun === state.runId;  // ignore output from superseded runs\n    const model = $('whisperModel').value;\n    modal('Transcribing locally…',\n      'Whisper runs on your CPU — roughly real time, so a 10 minute video takes about 10 minutes. ' +\n      'The first run also downloads the model.', { progress: 1, log: ' ' });\n    const res = await fetch('/api/transcribe', {\n      method: 'POST', headers: { 'content-type': 'application/json' },\n      body: JSON.stringify({ mediaId: state.media.id, language: state.style.locale || 'auto', model }),\n    });\n    const d = await res.json();\n    const done = () => { state.transcribing = false; $('btn-auto').disabled = !state.caps.whisper; };\n    if (!res.ok) { done(); return modal('Auto-caption unavailable', d.error || ''); }\n    const job = await poll(d.jobId, (j) => {\n      if (!mine()) return;\n      $('modalBar').style.width = (j.progress || 0) + '%';\n      const mins = j.elapsed != null ? `  ·  ${Math.floor(j.elapsed / 60)}m ${j.elapsed % 60}s` : '';\n      $('modalTitle').textContent =\n        j.phase === 'downloading model' ? `Downloading the model…${mins}`\n        : j.phase === 'transcribing'\n          ? `Transcribing… ${j.progress || 0}%${mins}`\n          : `Starting Whisper…${mins}`;\n      if (j.tail) {\n        const log = $('modalLog');\n        log.classList.remove('hidden');\n        log.textContent = j.tail;\n        log.scrollTop = log.scrollHeight;\n      }\n    });\n    done();\n    if (!mine()) return;\n    if (job.status === 'error') return modal('Transcription failed', job.error || '', { log: job.tail });\n    state.cues = resplit(parseSubtitles(job.result.srt), state.wordsPerCue, state.style.locale);\n    normalise(); renderCues(); drawCaption(true);\n    $('modal').classList.add('hidden');\n  };\n\n  // subtitle files\n  const dlSub = async (format) => {\n    const res = await fetch('/api/subtitle', {\n      method: 'POST', headers: { 'content-type': 'application/json' },\n      body: JSON.stringify(payload({ format })),\n    });\n    const blob = await res.blob();\n    const a = document.createElement('a');\n    a.href = URL.createObjectURL(blob);\n    a.download = 'captions.' + format;\n    a.click();\n  };\n  $('btn-srt').onclick = () => dlSub('srt');\n  $('btn-ass').onclick = () => dlSub('ass');\n\n  // export\n  $('btn-export').onclick = async () => {\n    if (!state.media) return;\n    if (!state.cues.length && !confirm('No captions yet — export anyway?')) return;\n    modal('Burning captions in…', 'ffmpeg is rendering with libass.', { progress: 1 });\n    const res = await fetch('/api/render', {\n      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload()),\n    });\n    const d = await res.json();\n    if (!res.ok) return modal('Export failed', d.error || '');\n    const job = await poll(d.jobId, (j) => { $('modalBar').style.width = (j.progress || 0) + '%'; });\n    if (job.status === 'error') return modal('Export failed', job.error || '', { log: job.tail });\n    modal('Done', 'Captioned video is ready.', { progress: 100, download: job.download });\n  };\n  $('modalClose').onclick = () => $('modal').classList.add('hidden');\n\n  // project files\n  $('btn-save').onclick = () => {\n    const blob = new Blob([JSON.stringify({\n      version: 1, cues: state.cues, style: state.style, transition: state.transition,\n      wordsPerCue: state.wordsPerCue, media: state.media?.name,\n    }, null, 2)], { type: 'application/json' });\n    const a = document.createElement('a');\n    a.href = URL.createObjectURL(blob);\n    a.download = 'caption-project.json';\n    a.click();\n  };\n  $('btn-load').onclick = () => $('projFile').click();\n  $('projFile').onchange = async (e) => {\n    const f = e.target.files[0];\n    if (!f) return;\n    try {\n      const p = JSON.parse(await f.text());\n      state.cues = (p.cues || []).map((c) => ({ ...c, start: +c.start, end: +c.end }));\n      state.style = { ...DEFAULT_STYLE, ...(p.style || {}) };\n      state.transition = p.transition || state.transition;\n      state.wordsPerCue = p.wordsPerCue || state.wordsPerCue;\n      normalise(); syncInputs(); buildTransitions(); renderCues(); drawCaption(true);\n    } catch (err) { modal('Could not open project', String(err.message || err)); }\n  };\n}\n\nboot();\n","type":"text/javascript; charset=utf-8"},"lib/ass.mjs":{"body":"// ASS (Advanced SubStation Alpha) generator.\n// libass handles every script ffmpeg can render: Latin, Cyrillic, Greek, CJK,\n// Arabic/Hebrew (bidi), Devanagari, Thai, Khmer, Ethiopic, emoji...\n\nconst CENTI = 100;\n\n/** #rrggbb + alpha(0..1) -> &HAABBGGRR */\nexport function assColor(hex, alpha = 1) {\n  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || '#ffffff').trim());\n  const rgb = m ? m[1] : 'ffffff';\n  const r = rgb.slice(0, 2), g = rgb.slice(2, 4), b = rgb.slice(4, 6);\n  const a = Math.round((1 - Math.min(1, Math.max(0, Number(alpha)))) * 255);\n  return ('&H' + a.toString(16).padStart(2, '0') + b + g + r).toUpperCase();\n}\n\nexport function assTime(seconds) {\n  const s = Math.max(0, Number(seconds) || 0);\n  const h = Math.floor(s / 3600);\n  const m = Math.floor((s % 3600) / 60);\n  const sec = s % 60;\n  return `${h}:${String(m).padStart(2, '0')}:${sec.toFixed(2).padStart(5, '0')}`;\n}\n\nfunction escapeText(t) {\n  return String(t)\n    .replace(/\\\\/g, '\\\\​')     // keep literal backslashes from being tags\n    .replace(/\\{/g, '\\\\{')\n    .replace(/\\}/g, '\\\\}')\n    .replace(/\\r/g, '');\n}\n\n/** 'auto' means we don't know the language; Intl wants undefined, not a bad tag. */\nconst loc = (l) => (l && l !== 'auto' ? l : undefined);\n\n/** Split text into segments, script-aware (works for CJK/Thai with no spaces). */\nfunction segment(text, locale, granularity) {\n  locale = loc(locale);\n  if (typeof Intl !== 'undefined' && Intl.Segmenter) {\n    try {\n      const seg = new Intl.Segmenter(locale || undefined, { granularity });\n      return [...seg.segment(text)].map((s) => ({ text: s.segment, wordLike: !!s.isWordLike }));\n    } catch { /* fall through */ }\n  }\n  if (granularity === 'grapheme') return [...text].map((c) => ({ text: c, wordLike: /\\S/.test(c) }));\n  return text.split(/(\\s+)/).filter(Boolean).map((t) => ({ text: t, wordLike: /\\S/.test(t) }));\n}\n\n/** Wrap one logical line to maxChars, respecting word boundaries of any script. */\nexport function wrapText(text, maxChars, locale) {\n  const limit = Math.max(6, Number(maxChars) || 42);\n  locale = loc(locale);\n  const out = [];\n  for (const para of String(text).split('\\n')) {\n    if (!para.trim()) { out.push(''); continue; }\n    let line = '';\n    for (const seg of segment(para, locale, 'word')) {\n      const candidate = line + seg.text;\n      if ([...candidate].length > limit && line.trim()) {\n        out.push(line.trimEnd());\n        line = seg.wordLike ? seg.text : '';\n      } else {\n        line = candidate;\n      }\n    }\n    if (line.trim()) out.push(line.trimEnd());\n  }\n  return out.length ? out : [''];\n}\n\n/** Anchor point for a given ASS alignment (1..9) in PlayRes coordinates. */\nfunction anchorPoint(style, W, H) {\n  const a = Number(style.alignment) || 2;\n  const ml = style.marginL, mr = style.marginR, mv = style.marginV;\n  const col = ((a - 1) % 3); // 0 left, 1 center, 2 right\n  const row = Math.floor((a - 1) / 3); // 0 bottom, 1 middle, 2 top\n  const x = col === 0 ? ml : col === 2 ? W - mr : W / 2;\n  const y = row === 0 ? H - mv : row === 2 ? mv : H / 2;\n  return { x: Math.round(x), y: Math.round(y), an: a };\n}\n\nexport const TRANSITIONS = [\n  'none', 'fade', 'slide-up', 'slide-down', 'slide-left', 'slide-right',\n  'pop', 'bounce', 'blur-in', 'zoom-out', 'typewriter', 'word-pop', 'karaoke',\n];\n\n/** Override tags that open a cue, for the simple (whole-line) transitions. */\nfunction transitionTags(kind, style, W, H, durMs) {\n  const t = Math.min(420, Math.max(90, Number(style.transitionMs) || 260));\n  const fade = `\\\\fad(${t},${Math.min(t, 200)})`;\n  const { x, y, an } = anchorPoint(style, W, H);\n  const d = Math.round(H * 0.06);\n  switch (kind) {\n    case 'none': return '';\n    case 'fade': return fade;\n    case 'slide-up': return `\\\\an${an}\\\\move(${x},${y + d},${x},${y},0,${t})${fade}`;\n    case 'slide-down': return `\\\\an${an}\\\\move(${x},${y - d},${x},${y},0,${t})${fade}`;\n    case 'slide-left': return `\\\\an${an}\\\\move(${x + d * 2},${y},${x},${y},0,${t})${fade}`;\n    case 'slide-right': return `\\\\an${an}\\\\move(${x - d * 2},${y},${x},${y},0,${t})${fade}`;\n    case 'pop': return `${fade}\\\\fscx55\\\\fscy55\\\\t(0,${t},\\\\fscx${style.scaleX}\\\\fscy${style.scaleY})`;\n    case 'bounce':\n      return `${fade}\\\\fscx118\\\\fscy118\\\\t(0,${Math.round(t * 0.55)},\\\\fscx92\\\\fscy92)` +\n             `\\\\t(${Math.round(t * 0.55)},${t},\\\\fscx${style.scaleX}\\\\fscy${style.scaleY})`;\n    case 'blur-in': return `${fade}\\\\blur6\\\\t(0,${t},\\\\blur0)`;\n    case 'zoom-out':\n      return `${fade}\\\\fscx135\\\\fscy135\\\\t(0,${Math.round(durMs)},\\\\fscx${style.scaleX}\\\\fscy${style.scaleY})`;\n    default: return fade;\n  }\n}\n\nfunction normStyle(raw, W, H) {\n  const s = raw || {};\n  const pct = (v, fallback, base) => Math.round(((Number(v) ?? fallback) / 100) * base);\n  return {\n    fontName: s.fontName || 'DejaVu Sans',\n    fontSize: Math.max(8, pct(s.fontSizePct, 5.6, H)),\n    primary: assColor(s.textColor, s.textOpacity ?? 1),\n    secondary: assColor(s.highlightColor || '#ffd400', 1),\n    outlineColor: assColor(s.outlineColor, s.outlineOpacity ?? 1),\n    backColor: assColor(s.boxColor || '#000000', s.boxOpacity ?? 0.6),\n    bold: s.bold ? -1 : 0,\n    italic: s.italic ? -1 : 0,\n    underline: s.underline ? -1 : 0,\n    strike: s.strike ? -1 : 0,\n    scaleX: Math.round(Number(s.scaleX ?? 100)),\n    scaleY: Math.round(Number(s.scaleY ?? 100)),\n    spacing: Number(s.spacing ?? 0),\n    angle: Number(s.angle ?? 0),\n    borderStyle: s.boxStyle === 'box' ? 3 : s.boxStyle === 'none' ? 1 : 1,\n    outline: s.boxStyle === 'none' ? 0 : Number(s.outlineWidth ?? 3),\n    shadow: Number(s.shadowWidth ?? 0),\n    alignment: Number(s.alignment ?? 2),\n    marginL: pct(s.marginXPct, 6, W),\n    marginR: pct(s.marginXPct, 6, W),\n    marginV: pct(s.marginYPct, 7, H),\n    uppercase: !!s.uppercase,\n    maxChars: Number(s.maxChars ?? 38),\n    transitionMs: Number(s.transitionMs ?? 260),\n    locale: s.locale || undefined,\n    highlightHex: s.highlightColor || '#ffd400',\n    textHex: s.textColor || '#ffffff',\n  };\n}\n\nfunction dialogue(start, end, text, layer = 0) {\n  return `Dialogue: ${layer},${assTime(start)},${assTime(end)},Default,,0,0,0,,${text}`;\n}\n\n/**\n * Build a full .ass document.\n * cues: [{ start, end, text, transition?, locale? }]\n */\nexport function buildAss({ cues = [], style = {}, transition = 'fade', width = 1920, height = 1080 }) {\n  const W = Math.max(16, Math.round(width));\n  const H = Math.max(16, Math.round(height));\n  const st = normStyle(style, W, H);\n\n  const header = [\n    '[Script Info]',\n    '; Generated by Caption Studio',\n    'ScriptType: v4.00+',\n    'WrapStyle: 2',\n    'ScaledBorderAndShadow: yes',\n    'YCbCr Matrix: None',\n    `PlayResX: ${W}`,\n    `PlayResY: ${H}`,\n    '',\n    '[V4+ Styles]',\n    'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour,' +\n      ' Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline,' +\n      ' Shadow, Alignment, MarginL, MarginR, MarginV, Encoding',\n    [\n      'Style: Default', st.fontName, st.fontSize, st.primary, st.secondary, st.outlineColor, st.backColor,\n      st.bold, st.italic, st.underline, st.strike, st.scaleX, st.scaleY, st.spacing, st.angle,\n      st.borderStyle, st.outline, st.shadow, st.alignment, st.marginL, st.marginR, st.marginV, 1,\n    ].join(','),\n    '',\n    '[Events]',\n    'Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text',\n  ];\n\n  const events = [];\n  for (const cue of cues) {\n    const start = Number(cue.start) || 0;\n    const end = Math.max(start + 0.05, Number(cue.end) || start + 1);\n    let raw = String(cue.text ?? '').trim();\n    if (!raw) continue;\n    if (st.uppercase) raw = raw.toLocaleUpperCase(loc(cue.locale || st.locale));\n    const locale = cue.locale || st.locale;\n    const lines = wrapText(raw, st.maxChars, locale);\n    const body = lines.map(escapeText).join('\\\\N');\n    const kind = cue.transition || transition || 'fade';\n    const durMs = (end - start) * 1000;\n\n    if (kind === 'karaoke') {\n      // Unsung text uses SecondaryColour, sung uses PrimaryColour -> swap inline.\n      const pieces = [];\n      for (const line of lines) {\n        const words = segment(line, locale, 'word').filter((s) => s.text.length);\n        const wordCount = words.filter((w) => w.wordLike).length || 1;\n        const per = Math.max(4, Math.round((durMs / wordCount) / 10)); // centiseconds\n        let out = '';\n        for (const w of words) {\n          out += w.wordLike ? `{\\\\kf${per}}${escapeText(w.text)}` : escapeText(w.text);\n        }\n        pieces.push(out);\n      }\n      const head = `{\\\\1c${assColor(st.highlightHex, 1)}\\\\2c${assColor(st.textHex, 1)}\\\\fad(90,90)}`;\n      events.push(dialogue(start, end, head + pieces.join('\\\\N')));\n      continue;\n    }\n\n    if (kind === 'typewriter' || kind === 'word-pop') {\n      const gran = kind === 'typewriter' ? 'grapheme' : 'word';\n      const units = segment(lines.join('\\n'), locale, gran).filter((s) => s.text.length);\n      const visible = units.filter((u) => u.wordLike || gran === 'grapheme');\n      const steps = Math.max(1, visible.length);\n      const step = (end - start) / steps;\n      let shown = '';\n      let i = 0;\n      const hide = `{\\\\alpha&HFF&}`;\n      const full = units.map((u) => u.text).join('');\n      for (const u of units) {\n        shown += u.text;\n        const isVisibleUnit = u.wordLike || gran === 'grapheme';\n        if (!isVisibleUnit) continue;\n        i += 1;\n        const segStart = start + step * (i - 1);\n        const segEnd = i === steps ? end : start + step * i;\n        const rest = full.slice(shown.length);\n        const body2 = escapeText(shown).replace(/\\n/g, '\\\\N') +\n          (rest ? hide + escapeText(rest).replace(/\\n/g, '\\\\N') : '');\n        events.push(dialogue(segStart, segEnd, `{\\\\fad(60,0)}${body2}`));\n      }\n      continue;\n    }\n\n    const tags = transitionTags(kind, st, W, H, durMs);\n    events.push(dialogue(start, end, tags ? `{${tags}}${body}` : body));\n  }\n\n  return header.concat(events).join('\\n') + '\\n';\n}\n\nfunction srtTime(seconds) {\n  const s = Math.max(0, Number(seconds) || 0);\n  const h = String(Math.floor(s / 3600)).padStart(2, '0');\n  const m = String(Math.floor((s % 3600) / 60)).padStart(2, '0');\n  const sec = String(Math.floor(s % 60)).padStart(2, '0');\n  const ms = String(Math.round((s % 1) * 1000)).padStart(3, '0');\n  return `${h}:${m}:${sec},${ms}`;\n}\n\nexport function buildSrt(cues = [], { maxChars = 38, locale } = {}) {\n  return cues\n    .filter((c) => String(c.text ?? '').trim())\n    .map((c, i) => {\n      const lines = wrapText(String(c.text).trim(), maxChars, c.locale || locale);\n      return `${i + 1}\\n${srtTime(c.start)} --> ${srtTime(c.end)}\\n${lines.join('\\n')}`;\n    })\n    .join('\\n\\n') + '\\n';\n}\n\nexport function buildVtt(cues = [], opts = {}) {\n  const body = buildSrt(cues, opts).replace(/,(\\d{3})/g, '.$1');\n  return 'WEBVTT\\n\\n' + body;\n}\n","type":"text/javascript; charset=utf-8"}};
// Caption Studio - a local, dependency-free captioning studio.
// Everything stays on this machine: uploads live in .work/, ffmpeg does the burn-in.

import http from 'node:http';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { spawn, execFile } from 'node:child_process';
import { fileURLToPath } from 'node:url';
const { buildAss, buildSrt, buildVtt, TRANSITIONS } = await import(
  'data:text/javascript;charset=utf-8;base64,' +
    Buffer.from(ASSETS['lib/ass.mjs'].body, 'utf8').toString('base64')
);

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PUBLIC = path.join(__dirname, 'public');
const WORK = process.env.CAPTION_STUDIO_WORK || path.join(os.homedir(), '.caption-studio');
const MEDIA = path.join(WORK, 'media');
const FONTS = path.join(WORK, 'fonts');
const JOBS = path.join(WORK, 'jobs');
const PORT = Number(process.env.PORT || 4321);
const HOST = process.env.HOST || '127.0.0.1';
const MAX_UPLOAD = Number(process.env.MAX_UPLOAD_BYTES || 4 * 1024 * 1024 * 1024);

for (const d of [MEDIA, FONTS, JOBS]) await fsp.mkdir(d, { recursive: true });

const MIME = {
  '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8', '.svg': 'image/svg+xml',
  '.mp4': 'video/mp4', '.webm': 'video/webm', '.mov': 'video/quicktime',
  '.mkv': 'video/x-matroska', '.m4v': 'video/mp4', '.avi': 'video/x-msvideo',
  '.ttf': 'font/ttf', '.otf': 'font/otf', '.woff': 'font/woff', '.woff2': 'font/woff2',
  '.ass': 'text/plain; charset=utf-8', '.srt': 'text/plain; charset=utf-8',
  '.vtt': 'text/vtt; charset=utf-8', '.txt': 'text/plain; charset=utf-8',
  '.ico': 'image/x-icon',
};

const jobs = new Map(); // id -> { status, progress, error, out, kind, result }

/* ------------------------------- helpers -------------------------------- */

const run = (cmd, args, opts = {}) =>
  new Promise((resolve, reject) => {
    execFile(cmd, args, { maxBuffer: 32 * 1024 * 1024, ...opts }, (err, stdout, stderr) =>
      err ? reject(Object.assign(err, { stdout, stderr })) : resolve({ stdout, stderr }));
  });

const has = async (bin) => { try { await run(bin, ['-version']); return true; } catch { return false; } };
const hasWhisper = async () => { try { await run('whisper', ['--help']); return true; } catch { return false; } };

function json(res, code, body) {
  const data = Buffer.from(JSON.stringify(body));
  res.writeHead(code, { 'content-type': 'application/json; charset=utf-8', 'content-length': data.length });
  res.end(data);
}

function text(res, code, body, type = 'text/plain; charset=utf-8', filename) {
  const data = Buffer.from(body, 'utf8');
  const headers = { 'content-type': type, 'content-length': data.length };
  if (filename) headers['content-disposition'] = `attachment; filename="${filename}"`;
  res.writeHead(code, headers);
  res.end(data);
}

async function readBody(req, limit = 4 * 1024 * 1024) {
  const chunks = [];
  let size = 0;
  for await (const c of req) {
    size += c.length;
    if (size > limit) throw new Error('payload too large');
    chunks.push(c);
  }
  return Buffer.concat(chunks);
}

const safeId = (s) => /^[A-Za-z0-9._-]{1,120}$/.test(String(s || '')) ? String(s) : null;

async function probe(file) {
  const { stdout } = await run('ffprobe', [
    '-v', 'error', '-print_format', 'json',
    '-show_entries', 'format=duration:stream=index,codec_type,codec_name,width,height,r_frame_rate',
    file,
  ]);
  const info = JSON.parse(stdout);
  const v = (info.streams || []).find((s) => s.codec_type === 'video') || {};
  const a = (info.streams || []).find((s) => s.codec_type === 'audio');
  const [num, den] = String(v.r_frame_rate || '0/1').split('/').map(Number);
  return {
    duration: Number(info.format?.duration) || 0,
    width: Number(v.width) || 1920,
    height: Number(v.height) || 1080,
    fps: den ? +(num / den).toFixed(3) : 0,
    videoCodec: v.codec_name || null,
    hasAudio: !!a,
  };
}

async function listFonts() {
  const families = new Set();
  try {
    const { stdout } = await run('fc-list', [':', 'family']);
    for (const line of stdout.split('\n')) {
      for (const fam of line.split(',')) {
        const f = fam.trim();
        if (f && !/[\u0000-\u001f]/.test(f)) families.add(f);
      }
    }
  } catch { /* fontconfig missing (bare Windows/macOS node) */ }
  // Fonts the user dropped into the studio are always offered.
  const custom = [];
  for (const f of await fsp.readdir(FONTS).catch(() => [])) {
    if (/\.(ttf|otf|ttc|woff2?)$/i.test(f)) {
      let fam = path.basename(f).replace(/\.[^.]+$/, '');
      try {
        const { stdout } = await run('fc-query', ['-f', '%{family[0]}', path.join(FONTS, f)]);
        if (stdout.trim()) fam = stdout.trim();
      } catch { /* keep filename */ }
      custom.push({ family: fam, file: f });
      families.add(fam);
    }
  }
  return { families: [...families].sort((a, b) => a.localeCompare(b)), custom };
}

/* -------------------------------- render -------------------------------- */

async function startRender(payload) {
  const id = safeId(payload.mediaId);
  if (!id) throw new Error('bad mediaId');
  const files = await fsp.readdir(MEDIA);
  const media = files.find((f) => f.startsWith(id + '.'));
  if (!media) throw new Error('media not found');
  const input = path.join(MEDIA, media);
  const meta = await probe(input);

  const jobId = crypto.randomUUID();
  const dir = path.join(JOBS, jobId);
  await fsp.mkdir(dir, { recursive: true });

  const ass = buildAss({
    cues: payload.cues || [],
    style: payload.style || {},
    transition: payload.transition || 'fade',
    width: meta.width,
    height: meta.height,
  });
  await fsp.writeFile(path.join(dir, 'subs.ass'), ass, 'utf8');

  const ext = payload.format === 'webm' ? 'webm' : 'mp4';
  const out = `captioned.${ext}`;
  const vf = `ass=filename=subs.ass:fontsdir=${path.relative(dir, FONTS).split(path.sep).join('/')}`;
  const args = ['-hide_banner', '-nostdin', '-y', '-i', input, '-vf', vf, '-map', '0:v:0'];
  if (meta.hasAudio) args.push('-map', '0:a:0?', '-c:a', ext === 'webm' ? 'libopus' : 'aac', '-b:a', '192k');
  if (ext === 'webm') args.push('-c:v', 'libvpx-vp9', '-crf', '32', '-b:v', '0');
  else args.push('-c:v', 'libx264', '-preset', payload.preset || 'veryfast',
                 '-crf', String(Number(payload.crf) || 20), '-pix_fmt', 'yuv420p', '-movflags', '+faststart');
  args.push(out);

  const job = { id: jobId, status: 'running', progress: 0, kind: 'render', dir, out, log: '', duration: meta.duration };
  jobs.set(jobId, job);

  const proc = spawn('ffmpeg', args, { cwd: dir });
  proc.stderr.on('data', (c) => {
    const s = c.toString();
    job.log = (job.log + s).slice(-8000);
    const m = /time=(\d+):(\d+):(\d+\.\d+)/.exec(s);
    if (m && meta.duration) {
      const t = (+m[1]) * 3600 + (+m[2]) * 60 + (+m[3]);
      job.progress = Math.min(99, Math.round((t / meta.duration) * 100));
    }
  });
  proc.on('error', (err) => { job.status = 'error'; job.error = err.message; });
  proc.on('close', (code) => {
    if (job.status === 'error') return;
    if (code === 0) { job.status = 'done'; job.progress = 100; }
    else { job.status = 'error'; job.error = `ffmpeg exited ${code}`; }
  });
  return { jobId, meta };
}

async function startTranscribe(payload) {
  const id = safeId(payload.mediaId);
  if (!id) throw new Error('bad mediaId');
  const files = await fsp.readdir(MEDIA);
  const media = files.find((f) => f.startsWith(id + '.'));
  if (!media) throw new Error('media not found');

  const jobId = crypto.randomUUID();
  const dir = path.join(JOBS, jobId);
  await fsp.mkdir(dir, { recursive: true });
  const meta = await probe(path.join(MEDIA, media));
  const wav = path.join(dir, 'audio.wav');
  await run('ffmpeg', ['-hide_banner', '-nostdin', '-y', '-i', path.join(MEDIA, media),
                       '-vn', '-ac', '1', '-ar', '16000', wav]);

  const MODELS = new Set(['tiny', 'base', 'small', 'medium', 'large-v3', 'turbo']);
  const model = MODELS.has(payload.model) ? payload.model : 'small';
  const args = [wav, '--model', model, '--output_format', 'srt', '--verbose', 'True',
                '--output_dir', dir, '--task', payload.translate ? 'translate' : 'transcribe'];
  if (payload.language && payload.language !== 'auto') args.push('--language', payload.language);

  const job = {
    id: jobId, status: 'running', progress: 0, kind: 'transcribe', dir, log: '',
    phase: 'starting', duration: meta.duration, startedAt: Date.now(),
  };
  jobs.set(jobId, job);
  console.log(`  transcribing with whisper (${model} model) - this runs on CPU and takes a while`);
  const proc = spawn('whisper', args, { cwd: dir });

  // Whisper prints each segment as it finishes: "[00:12.000 --> 00:15.400]  text".
  // The last timestamp against the media duration is real progress, not a guess.
  const STAMP = /\[(?:(\d+):)?(\d{1,2}):(\d{2})\.\d{3}\s*-->/g;
  const RANK = { starting: 0, 'downloading model': 1, 'loading model': 2, transcribing: 3 };
  const bump = (phase) => { if (RANK[phase] > RANK[job.phase]) job.phase = phase; };
  const onOut = (c) => {
    const chunk = c.toString();
    job.log = (job.log + chunk).slice(-8000);
    process.stdout.write(chunk);          // visible in the terminal you launched from
    STAMP.lastIndex = 0;
    let m, last = null;
    while ((m = STAMP.exec(chunk)) !== null) last = m;
    if (last) {
      bump('transcribing');
      const t = (Number(last[1]) || 0) * 3600 + Number(last[2]) * 60 + Number(last[3]);
      if (meta.duration) job.progress = Math.min(99, Math.round((t / meta.duration) * 100));
    }
    // Whisper says these once the weights are in and it is actually working.
    if (/FP16 is not supported|Detecting language|Detected language|Performing/i.test(chunk)) {
      bump('transcribing');
    } else if (/%\|/.test(chunk)) {
      bump('downloading model');
    }
  };
  proc.stdout.on('data', onOut);
  proc.stderr.on('data', onOut);
  proc.on('error', (err) => { job.status = 'error'; job.error = err.message; });
  proc.on('close', async (code) => {
    if (job.status === 'error') return;
    if (code !== 0) { job.status = 'error'; job.error = `whisper exited ${code}`; return; }
    const srt = (await fsp.readdir(dir)).find((f) => f.endsWith('.srt'));
    if (!srt) { job.status = 'error'; job.error = 'no .srt produced'; return; }
    job.result = { srt: await fsp.readFile(path.join(dir, srt), 'utf8') };
    job.status = 'done';
    job.progress = 100;
  });
  return { jobId };
}

/* -------------------------------- routing ------------------------------- */

async function readAsset(rel) {
  return ASSETS[rel] || null;
}

async function sendAsset(res, urlPath) {
  const rel = urlPath === '/' ? 'index.html' : decodeURIComponent(urlPath).replace(/^\/+/, '');
  if (rel.includes('..') || path.isAbsolute(rel)) return json(res, 403, { error: 'forbidden' });
  const asset = await readAsset(rel);
  if (!asset) return json(res, 404, { error: 'not found' });
  res.writeHead(200, {
    'content-type': asset.type,
    'content-length': Buffer.byteLength(asset.body),
    'cache-control': 'no-cache',
  });
  res.end(asset.body);
}

function serveRange(req, res, file) {
  fs.stat(file, (err, st) => {
    if (err || !st.isFile()) return json(res, 404, { error: 'not found' });
    const type = MIME[path.extname(file).toLowerCase()] || 'application/octet-stream';
    const range = req.headers.range;
    if (range) {
      const m = /bytes=(\d*)-(\d*)/.exec(range);
      let start = m[1] ? Number(m[1]) : 0;
      let end = m[2] ? Number(m[2]) : st.size - 1;
      if (Number.isNaN(start) || Number.isNaN(end) || start > end || start >= st.size) {
        res.writeHead(416, { 'content-range': `bytes */${st.size}` });
        return res.end();
      }
      end = Math.min(end, st.size - 1);
      res.writeHead(206, {
        'content-type': type,
        'content-length': end - start + 1,
        'content-range': `bytes ${start}-${end}/${st.size}`,
        'accept-ranges': 'bytes',
      });
      return fs.createReadStream(file, { start, end }).pipe(res);
    }
    res.writeHead(200, { 'content-type': type, 'content-length': st.size, 'accept-ranges': 'bytes' });
    fs.createReadStream(file).pipe(res);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  const p = url.pathname;
  try {
    /* ---- capabilities ---- */
    if (p === '/api/capabilities' && req.method === 'GET') {
      const [ffmpeg, ffprobe, whisper, fonts] = await Promise.all([
        has('ffmpeg'), has('ffprobe'), hasWhisper(), listFonts(),
      ]);
      return json(res, 200, {
        ffmpeg, ffprobe, whisper, transitions: TRANSITIONS,
        fonts: fonts.families, customFonts: fonts.custom,
        platform: `${os.type()} ${os.arch()}`, work: WORK,
      });
    }

    /* ---- upload video: raw PUT body, no multipart needed ---- */
    if (p === '/api/upload' && req.method === 'PUT') {
      const name = url.searchParams.get('name') || 'video.mp4';
      const ext = (path.extname(name).toLowerCase().match(/^\.[a-z0-9]{1,5}$/) || ['.mp4'])[0];
      const id = crypto.randomUUID();
      const dest = path.join(MEDIA, id + ext);
      await new Promise((resolve, reject) => {
        let size = 0;
        const ws = fs.createWriteStream(dest);
        req.on('data', (c) => {
          size += c.length;
          if (size > MAX_UPLOAD) { req.destroy(); ws.destroy(); reject(new Error('file too large')); }
        });
        req.pipe(ws);
        ws.on('finish', resolve);
        ws.on('error', reject);
        req.on('error', reject);
      });
      let meta;
      try { meta = await probe(dest); }
      catch (e) { await fsp.unlink(dest).catch(() => {}); return json(res, 400, { error: 'not a readable video file' }); }
      return json(res, 200, { id, name, url: `/api/media/${id}${ext}`, ...meta });
    }

    /* ---- stream uploaded media (Range for scrubbing) ---- */
    if (p.startsWith('/api/media/') && req.method === 'GET') {
      const f = safeId(p.slice('/api/media/'.length));
      if (!f) return json(res, 400, { error: 'bad name' });
      return serveRange(req, res, path.join(MEDIA, f));
    }

    /* ---- custom fonts: upload + serve for browser preview ---- */
    if (p === '/api/fonts' && req.method === 'PUT') {
      const name = path.basename(url.searchParams.get('name') || 'font.ttf');
      if (!/\.(ttf|otf|ttc|woff2?)$/i.test(name)) return json(res, 400, { error: 'need .ttf/.otf/.ttc/.woff2' });
      const buf = await readBody(req, 64 * 1024 * 1024);
      const file = name.replace(/[^A-Za-z0-9._-]/g, '_');
      await fsp.writeFile(path.join(FONTS, file), buf);
      const { custom } = await listFonts();
      const entry = custom.find((c) => c.file === file);
      return json(res, 200, { file, family: entry?.family || file.replace(/\.[^.]+$/, ''), url: `/api/fonts/${file}` });
    }
    if (p.startsWith('/api/fonts/') && req.method === 'GET') {
      const f = safeId(p.slice('/api/fonts/'.length));
      if (!f) return json(res, 400, { error: 'bad name' });
      return serveRange(req, res, path.join(FONTS, f));
    }

    /* ---- sidecar subtitle download ---- */
    if (p === '/api/subtitle' && req.method === 'POST') {
      const body = JSON.parse((await readBody(req, 16 * 1024 * 1024)).toString('utf8'));
      const fmt = body.format === 'srt' ? 'srt' : body.format === 'vtt' ? 'vtt' : 'ass';
      const opts = { maxChars: body.style?.maxChars ?? 38, locale: body.style?.locale };
      const out = fmt === 'ass'
        ? buildAss({ cues: body.cues || [], style: body.style || {}, transition: body.transition,
                     width: body.width || 1920, height: body.height || 1080 })
        : fmt === 'srt' ? buildSrt(body.cues || [], opts) : buildVtt(body.cues || [], opts);
      return text(res, 200, out, MIME['.' + fmt] || 'text/plain; charset=utf-8', `captions.${fmt}`);
    }

    /* ---- render / transcribe ---- */
    if (p === '/api/render' && req.method === 'POST') {
      const body = JSON.parse((await readBody(req, 16 * 1024 * 1024)).toString('utf8'));
      const { jobId } = await startRender(body);
      return json(res, 202, { jobId });
    }
    if (p === '/api/transcribe' && req.method === 'POST') {
      if (!await hasWhisper()) return json(res, 501, { error: 'whisper CLI not installed' });
      const body = JSON.parse((await readBody(req)).toString('utf8'));
      const { jobId } = await startTranscribe(body);
      return json(res, 202, { jobId });
    }
    if (p.startsWith('/api/job/') && req.method === 'GET') {
      const job = jobs.get(p.slice('/api/job/'.length));
      if (!job) return json(res, 404, { error: 'no such job' });
      return json(res, 200, {
        id: job.id, status: job.status, progress: job.progress, kind: job.kind,
        error: job.error || null, result: job.result || null,
        phase: job.phase || null,
        elapsed: job.startedAt ? Math.round((Date.now() - job.startedAt) / 1000) : null,
        tail: job.log ? job.log.slice(-1200) : undefined,
        download: job.status === 'done' && job.kind === 'render' ? `/api/download/${job.id}` : null,
      });
    }
    if (p.startsWith('/api/download/') && req.method === 'GET') {
      const job = jobs.get(p.slice('/api/download/'.length));
      if (!job || job.status !== 'done' || job.kind !== 'render') return json(res, 404, { error: 'not ready' });
      const file = path.join(job.dir, job.out);
      const st = await fsp.stat(file);
      res.writeHead(200, {
        'content-type': MIME[path.extname(file)] || 'application/octet-stream',
        'content-length': st.size,
        'content-disposition': `attachment; filename="${job.out}"`,
      });
      return fs.createReadStream(file).pipe(res);
    }

    /* ---- shared subtitle engine, reused by the browser preview ---- */
    if (p === '/lib/ass.mjs' && req.method === 'GET') return sendAsset(res, 'lib/ass.mjs');

    if (p.startsWith('/api/')) return json(res, 404, { error: 'unknown endpoint' });
    return sendAsset(res, p);
  } catch (err) {
    return json(res, 500, { error: String(err.message || err) });
  }
});

server.listen(PORT, HOST, async () => {
  const ff = await has('ffmpeg');
  console.log(`\n  Caption Studio  ->  http://${HOST}:${PORT}\n`);
  console.log(`  work dir : ${WORK}`);
  console.log(`  ffmpeg   : ${ff ? 'found' : 'MISSING - install ffmpeg to export video'}`);
  console.log(`  whisper  : ${await hasWhisper() ? 'found (auto-captions enabled)' : 'not installed (import or type captions)'}\n`);
});
